```ctl
//#CTL2

function integer transform() {
    RegionalSupportPolicyLookup_Record policy = lookup(RegionalSupportPolicyLookup).get($in.0.customer_region);
    integer basePoints;
    decimal escalationAmount;
    boolean restrictedService;
    if (isnull(policy.customer_region)) {
        basePoints = 20;
        escalationAmount = 0D;
        restrictedService = false;
    } else {
        basePoints = policy.standard_priority_points;
        escalationAmount = policy.escalation_amount_inr;
        restrictedService = policy.restricted_service;
    }

    integer priority = basePoints;
    if ($in.0.unresolved_contacts_7d >= 3L) priority += 30;
    if (!isnull($in.0.disputed_amount_inr) && $in.0.disputed_amount_inr > escalationAmount) priority += 20;
    if ($in.0.customer_tenure_months < 6) priority += 15;
    if ($in.0.callback_requested) priority += 10;
    if (startsWith($in.0.service_category, "UPI_")) priority += 10;
    if (priority > 100) priority = 100;

    string priorityLevel;
    if (priority >= 75) priorityLevel = "URGENT";
    else if (priority >= 50) priorityLevel = "PRIORITY";
    else if (priority >= 25) priorityLevel = "ROUTINE";
    else priorityLevel = "STANDARD";

    boolean contactAvailable = !isnull($in.0.contact_number) && $in.0.contact_number != "";
    string maskedContact = contactAvailable
        ? "XXXX" + substring($in.0.contact_number,
            max(length($in.0.contact_number) - 4, 0), 4)
        : "CONTACT_UNAVAILABLE";

    string escalationReason = "PRIORITY_THRESHOLD";
    if (restrictedService) escalationReason = "RESTRICTED_SERVICE";
    else if ($in.0.callback_requested && $in.0.unresolved_contacts_7d >= 2L) escalationReason = "REPEAT_CONTACTS_WITH_CALLBACK";
    else if (priorityLevel == "URGENT" && !contactAvailable) escalationReason = "MISSING_CONTACT_FOR_URGENT_CASE";
    else if (!isnull($in.0.disputed_amount_inr) && $in.0.disputed_amount_inr > escalationAmount) escalationReason = "HIGH_DISPUTE_AMOUNT";
    else if ($in.0.customer_tenure_months < 6) escalationReason = "NEW_BANKING_CUSTOMER";
    else if (startsWith($in.0.service_category, "UPI_")) escalationReason = "UPI_SERVICE_ISSUE";
    else if (priorityLevel != "URGENT") escalationReason = null;

    integer outPort;
    if (restrictedService || ($in.0.callback_requested && $in.0.unresolved_contacts_7d >= 2L)
        || (priorityLevel == "URGENT" && !contactAvailable)) outPort = 0;
    else outPort = 1;

    if (outPort == 0) {
        $out.0.case_reference = $in.0.case_reference;
        $out.0.support_priority = priority;
        $out.0.priority_level = priorityLevel;
        $out.0.escalation_reason = escalationReason;
        $out.0.case_date = extractDate($in.0.opened_at);
        $out.0.masked_contact_number = maskedContact;
    } else {
        $out.1.case_reference = $in.0.case_reference;
        $out.1.support_priority = priority;
        $out.1.priority_level = priorityLevel;
        $out.1.handling_code = priorityLevel == "STANDARD" ? "STANDARD_ASSISTANCE"
            : priorityLevel == "ROUTINE" ? "ROUTINE_FOLLOW_UP" : "PRIORITY_MONITORING";
        $out.1.case_date = extractDate($in.0.opened_at);
    }
    return outPort;
}
