The original retains the previous group state and can let a null amount turn the decimal sum into null. Capture the key once per group, collect bad inputs, and reset every retained value.

```ctl
//#CTL2
string g_groupId;
integer g_cnt = 0;
decimal g_sum = 0D;
string[] g_bad = [];

function integer append() {
    if (g_cnt == 0) g_groupId = $in.0.group_id;
    g_cnt++;

    if (isnull($in.0.amount_str)) {
        g_bad = append(g_bad, "<null>");
        return OK;
    }

    try {
        g_sum = g_sum + str2decimal($in.0.amount_str);
    } catch (CTLException ex) {
        g_bad = append(g_bad, $in.0.amount_str);
    }
    return OK;
}

function integer appendOnError(string errorMessage, string stackTrace) {
    printLog(warn, "append failed: " + errorMessage);
    g_bad = append(g_bad, "<append-error>");
    return OK;
}

function integer transform() {
    $out.0.group_id = g_groupId;
    $out.0.sum_amount = g_sum;
    $out.0.bad_values = length(g_bad) == 0 ? null : join(",", g_bad);
    return OK;
}

function void clean() {
    g_groupId = null;
    g_cnt = 0;
    g_sum = 0D;
    g_bad = [];
}
```

