Task: Generate 500 records. Use 10 Western European dispatch areas, with 50 appointments per area. Schedule planned visits across the next 10 business days. Use realistic route distances in kilometres and varying engineer daily workloads. Set site_access_confirmed to false or null for occasional customer-access issues. Set appointment_state to ESCALATED when site_access_confirmed is false or null, or when engineer_daily_load is 8 or greater and route_distance_km exceeds 45 km; otherwise set it to SCHEDULED.

Incorrect assistant response to fix:
Configure the DataGenerator component to emit 500 records.

```ctl
//#CTL2
const string[] DISPATCH_AREAS = [
    "London", "Manchester", "Birmingham", "Leeds", "Glasgow",
    "Edinburgh", "Dublin", "Cardiff", "Belfast", "Bristol"
];
const integer RECORDS_PER_AREA = 50;
const integer TOTAL_RECORDS = 500;
const integer BUSINESS_DAYS = 10;

integer rowCounter = 0;

function integer generate() {
    integer areaIndex = rowCounter / RECORDS_PER_AREA;
    integer businessDayIndex = (rowCounter % RECORDS_PER_AREA) % BUSINESS_DAYS;
    date plannedDate = today();

    integer businessDaysScheduled = 0;
    while (businessDaysScheduled < businessDayIndex) {
        plannedDate = dateAdd(plannedDate, 1L, day);
        integer dayOfWeek = getDayOfWeek(plannedDate);
        if (dayOfWeek != 6 && dayOfWeek != 7) {
            businessDaysScheduled = businessDaysScheduled + 1;
        }
    }

    integer distanceTenths = randomInteger(120, 780);
    integer engineerLoad = randomInteger(3, 9);
    integer accessRoll = randomInteger(1, 100);
    boolean accessConfirmed;
    if (accessRoll <= 70) {
        accessConfirmed = true;
    } else if (accessRoll <= 85) {
        accessConfirmed = false;
    } else {
        accessConfirmed = null;
    }
    decimal routeDistance = distanceTenths / 10D;
    string appointmentState = (isnull(accessConfirmed) || !accessConfirmed
        || (engineerLoad >= 8 && routeDistance > 45D))
        ? "ESCALATED" : "SCHEDULED";

    $out.0.work_order_ref = 700000000L + rowCounter + 1L;
    $out.0.planned_visit = plannedDate;
    $out.0.dispatch_area = DISPATCH_AREAS[areaIndex];
    $out.0.route_distance_km = routeDistance;
    $out.0.engineer_daily_load = engineerLoad;
    $out.0.site_access_confirmed = accessConfirmed;
    $out.0.appointment_state = appointmentState;
    rowCounter = rowCounter + 1;
    return ALL;
}
```

