  <Record name="BeverageOnboardingIn_Record" type="delimited">
    <Field name="application_ref" type="string" nullable="false"/>
    <Field name="enterprise_name" type="string" nullable="false"/>
    <Field name="market_iso" type="string" nullable="false"/>
    <Field name="trade_classification" type="string" nullable="false"/>
