            standardTerms = 7;
            appliedTerms = "PRIORITY";
            break;
        case "DOMESTIC":
            standardTerms = 14;
            appliedTerms = "DOMESTIC";
            break;
        case "REGIONAL":
            standardTerms = 21;
            appliedTerms = "REGIONAL";
            break;
        case "PORT_CORRIDOR":
            standardTerms = 30;
            appliedTerms = "PORT_CORRIDOR";
            break;
        default:
            standardTerms = 21;
            appliedTerms = "REGIONAL";
    }
