        reviewReason = "PAYMENT_HOLD";
    } else if (isnull($in.0.customs_release_date)) {
        paymentStatus = "DOCUMENT_REVIEW";
        reviewReason = "CUSTOMS_RELEASE_MISSING";
    } else if ($in.0.billed_amount <= 0D) {
        paymentStatus = "INVALID_INVOICE";
        reviewReason = "INVALID_AMOUNT";
