    }
    $out.0.payment_status = paymentStatus;
    $out.0.review_reason = reviewReason;

    decimal amountForPayment = 0D;
    if (paymentStatus == "OVERDUE_PAYMENT" || paymentStatus == "PAYMENT_WINDOW") {
        amountForPayment = $in.0.billed_amount;
    }
    $out.0.amount_for_payment = amountForPayment;

    return ALL;
}
