    // payment_method is nullable
    if (!isnull($in.0.payment_method)) {
        switch ($in.0.payment_method) {
            case "CARD":
                acc.card_payments = acc.card_payments + 1;
                break;
            case "CASH":
                acc.cash_payments = acc.cash_payments + 1;
                break;
            default:
                break;
        }
    }

    return false;
}

function boolean finishGroup(SalesAgg acc) {
    // No additional accumulator-level calculations needed
    return true;
}

function int32 updateTransform(integer counter, SalesAgg acc) {
    return SKIP;
}

function integer transform(integer counter, SalesAgg acc) {
    // Emit one summary record per group
    if (counter > 0) {
        return SKIP;
    }

    $out.0.store_id = g_store_id;
    $out.0.business_date = g_business_date;

    $out.0.total_receipts = acc.total_receipts;
    $out.0.total_items = acc.total_items;

    // total_net = total_gross - total_discount (both non-nullable here)
